insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('e7fb9c7e-d23c-4929-ae19-0e3694b98f9f', 'Multiplying large numbers vertically. Chapter 1 opener. Multiplication: review of multiplying a four-digit number by a three-digit number; multiplicand, multiplier, product. Worked example: 4614 × 365 = 1684110 (vehicles crossing a bridge in a year)', 5, 'mathematics', 1, 'c1-l1', 'g5m-c1-multiply-vertical', 'Multiplying large numbers vertically', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 1, 8, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('8e435456-9f98-4a31-a980-d20c1e42f2e9', 'Multiplying large numbers vertically. Multiplying a four-digit number by a three-digit number and a four-digit number by a four-digit number vertically, using partial products. Worked example: 8536 × 972 (mobile phones sold); 4765 × 2354', 5, 'mathematics', 1, 'c1-l1', 'g5m-c1-multiply-vertical', 'Multiplying large numbers vertically', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 2, 9, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('3da92051-52ca-4599-a7d2-2266f55ff289', 'Multiplying large numbers vertically. Fill-in-the-blank vertical multiplications and practice multiplying 4- and 5-digit numbers by 4-digit numbers vertically.', 5, 'mathematics', 1, 'c1-l1', 'g5m-c1-multiply-vertical', 'Multiplying large numbers vertically', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 3, 10, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('730f9fbb-8e94-487f-a6e8-a0e8a9582ef7', 'Multiplying horizontally by breaking up a number. Multiplying horizontally by breaking the multiplier or the multiplicand into thousands, hundreds, tens and ones; the product does not change. Worked example: 6042 × 1514 = 6042 × (1000 + 500 + 10 + 4)', 5, 'mathematics', 1, 'c1-l2', 'g5m-c1-multiply-horizontal', 'Multiplying horizontally by breaking up a number', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 4, 11, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('ee3fa38d-6249-4309-ae93-207c14cf3c46', 'Multiplying numbers that end in zeros. Simple method when multiplicand and multiplier end in zeros: multiply the non-zero parts, then put the total number of zeros at the end. Worked example: 7400 × 2900 = 74 × 29 × 10000 = 21460000; 49730 × 9800', 5, 'mathematics', 1, 'c1-l3', 'g5m-c1-multiply-zeros', 'Multiplying numbers that end in zeros', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 5, 12, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('0d6c879e-25a1-487d-a039-542d8ce1ce30', 'Simple method: multiplying by 99, 999, 9999. Simple method for multiplying by 99, 999, 9999: write the number as (100 − 1), (1000 − 1) etc. and subtract. Worked example: 99 × 24 = (100 − 1) × 24; 999 × 32; 9999 × 98725', 5, 'mathematics', 1, 'c1-l4', 'g5m-c1-multiply-simple-method', 'Simple method: multiplying by 99, 999, 9999', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 6, 13, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('218cfcbe-44de-40a5-ac4b-b81b834bda03', 'Simple method: multiplying by 99, 999, 9999. Word problem using the simple method (1999 = 2000 − 1) and making a mathematical story for a multiplication. Worked example: 89753 × 1999 (blankets for cold-affected families)', 5, 'mathematics', 1, 'c1-l4', 'g5m-c1-multiply-simple-method', 'Simple method: multiplying by 99, 999, 9999', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 7, 14, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('00f7675f-615f-40bb-a7ee-0e85f9628f52', 'Division by a two-digit number. Division: dividing a four-digit number by a two-digit number; dividend, divisor, quotient, remainder. Worked example: 4275 ÷ 45 = 95 (money shared among 45 students)', 5, 'mathematics', 1, 'c1-l5', 'g5m-c1-divide-two-digit', 'Division by a two-digit number', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 8, 15, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('d0c10ce9-fcbc-4b82-a170-740c704228b8', 'Division by a three-digit number and checking the answer. Dividing a four-digit number by a three-digit number; checking with Divisor × Quotient + Remainder = Dividend; remainder is always smaller than the divisor. Worked example: 6674 ÷ 214 = 31 remainder 40', 5, 'mathematics', 1, 'c1-l6', 'g5m-c1-divide-three-digit', 'Division by a three-digit number and checking the answer', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 9, 16, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('a8bfd94b-1117-4cb5-a497-4df3e826b6b0', 'Division by a three-digit number and checking the answer. Dividing a five-digit number by a three-digit number step by step and verifying; fill-in-the-blank divisions. Worked example: 69738 ÷ 245 = 284 remainder 158', 5, 'mathematics', 1, 'c1-l6', 'g5m-c1-divide-three-digit', 'Division by a three-digit number and checking the answer', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 10, 17, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('2303e505-246c-4d74-a67a-31bcc1e7662e', 'Dividing by 10 and 100. Division practice; checking given quotients and remainders; dividing by 10 and 100 by cutting off digits from the right (they form the remainder). Worked example: 2412 ÷ 10 = 241 r 2; 3264 ÷ 100 = 32 r 64; 63973 ÷ 100 = 639 r 73', 5, 'mathematics', 1, 'c1-l7', 'g5m-c1-divide-by-10-100', 'Dividing by 10 and 100', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 11, 18, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('2cc87606-2765-4247-af5b-195129a5a81f', 'Division word problems. Relation among dividend, divisor, quotient and remainder when dividing by 10 or 100; word problem on profit per month and per employee. Worked example: 4680000 ÷ 12 and 4680000 ÷ 150 (biscuit factory profit)', 5, 'mathematics', 1, 'c1-l8', 'g5m-c1-division-word-problems', 'Division word problems', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 12, 19, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('8878317c-7593-459b-a2d0-7af4118396e7', 'Division word problems. Division word problems, including answers given as ordinal numbers (in which round / which month). Worked example: 96250 ÷ 275 (dam repair); 10000 ÷ 900 → 12th round', 5, 'mathematics', 1, 'c1-l8', 'g5m-c1-division-word-problems', 'Division word problems', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 13, 20, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('d5971f5e-0030-44b5-aa2f-9ef9fcebbc2a', 'Let us try (self-check) for multiplication and division: vertical multiplication, long division, word problem, verification formula, simple method.', 5, 'mathematics', 1, null, null, 'let_us_try', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 14, 21, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('1b3b7add-8af5-4c09-ab99-5363501615d0', 'Let us do (chapter 1): multiple-choice questions, horizontal and vertical multiplication, division.', 5, 'mathematics', 1, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 15, 22, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('e7435b0c-7c90-43d7-a7c8-a268367bd219', 'Let us do (chapter 1, continued): simple-method multiplication and division, true/false checks and word problems.', 5, 'mathematics', 1, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 16, 23, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('cadc2d25-eb05-4045-a171-8de7dadf82ec', 'Unknown numbers in mathematical sentences. Chapter 2 opener. Writing a mathematical sentence with an unknown number (A) and finding its value by trying values or using the inverse operation. Worked example: 48 ÷ A = 8, so A = 48 ÷ 8 = 6', 5, 'mathematics', 2, 'c2-l1', 'g5m-c2-unknown-in-sentence', 'Unknown numbers in mathematical sentences', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 17, 24, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('48164e3c-6759-47c0-a8c1-f21723f8d118', 'Open and closed sentences. Open and closed mathematical sentences; true and false sentences; finding the value that makes an open sentence true. Worked example: 6 × 4 = 24 (true), 25 + 4 > 30 (false), 9 + A = 21 (open)', 5, 'mathematics', 2, 'c2-l2', 'g5m-c2-open-closed-sentences', 'Open and closed sentences', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 18, 25, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('2a2c22bd-611e-4dc8-ae2a-c28e1f8a33f2', 'Relations between two quantities. Forming a sentence with two unknowns and finding the relation between them; substituting values. Worked example: A × 24 + 150 = 246; A × 48 = B − 116', 5, 'mathematics', 2, 'c2-l3', 'g5m-c2-relation-two-quantities', 'Relations between two quantities', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 19, 26, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('56990d19-d71c-496a-ab31-22c5a00b81df', 'Order of operations and brackets. Order of operations: left to right; multiplication/division before addition/subtraction; brackets first in the order ( ), { }, [ ]. Worked example: 3 + {(14 − 10) × (20 − 15) + 30} ÷ 25 − 4 = 1; 12 ÷ 2 × 3 vs 12 ÷ (2 × 3)', 5, 'mathematics', 2, 'c2-l4', 'g5m-c2-order-of-operations', 'Order of operations and brackets', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 20, 27, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('857e8e89-dd6c-434b-a69b-5f8aea6a79e5', 'Word problems with brackets. Word problems written as a single mathematical sentence with brackets. Worked example: 6432 + 231 − 153 workers; price of one banana from 3 dozen eggs and 5 hali bananas costing 620 taka', 5, 'mathematics', 2, 'c2-l5', 'g5m-c2-bracket-word-problems', 'Word problems with brackets', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 21, 28, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('1ab72d3e-e9a9-46e7-acd9-c42970228540', 'Word problems with brackets. More word problems solved with brackets in two ways (step by step or as one sentence). Worked example: 2000 − (240 × 5 + 120 × 3) = 440 taka returned', 5, 'mathematics', 2, 'c2-l5', 'g5m-c2-bracket-word-problems', 'Word problems with brackets', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 22, 29, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('6dd9cb5f-f9b9-4753-a088-96a1094ee7e4', 'Sum-and-difference and ''times as many'' problems. Sharing a total cost equally; sum-and-difference problem solved with a bar picture. Worked example: Ayesha and Amena have 12756 taka together, Ayesha has 1120 more', 5, 'mathematics', 2, 'c2-l6', 'g5m-c2-sum-difference-problems', 'Sum-and-difference and ''times as many'' problems', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 23, 30, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('f324aac7-77f5-455d-a1ac-9342b915626e', 'Sum-and-difference and ''times as many'' problems. ''Times as many'' age problem solved with a bar picture; practice problems. Worked example: Mother and daughter ages sum to 56, mother is 3 times the daughter', 5, 'mathematics', 2, 'c2-l6', 'g5m-c2-sum-difference-problems', 'Sum-and-difference and ''times as many'' problems', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 24, 31, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('583aa7cf-d716-4de4-afcc-1115a7dd2871', 'Unitary method. Unitary method: first find the value of one unit, then of many units. Worked example: 12 mangoes cost 264 taka → 1 mango 264 ÷ 12 → 35 mangoes 264 ÷ 12 × 35', 5, 'mathematics', 2, 'c2-l7', 'g5m-c2-unitary-method', 'Unitary method', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 25, 32, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('a6acb198-6137-4264-af12-e18a8e295e58', 'Unitary method. Unitary method practice with a table (direct proportion: more days, more cloth). Worked example: A weaver weaves 24 m of cloth in 3 days', 5, 'mathematics', 2, 'c2-l7', 'g5m-c2-unitary-method', 'Unitary method', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 26, 33, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('ec8a37b7-2473-4142-a116-729c09ef932f', 'Unitary method. Unitary method where fewer workers need more time (multiply first, then divide); investment and profit. Worked example: 8 persons dig a well in 2 days → 2 persons need 8 × 2 ÷ 2 days', 5, 'mathematics', 2, 'c2-l7', 'g5m-c2-unitary-method', 'Unitary method', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 27, 34, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('c442740d-a0fc-43ff-a713-82db3c3541d5', 'Let us try (self-check) for order of operations, unitary method and bracket word problems.', 5, 'mathematics', 2, null, null, 'let_us_try', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 28, 35, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('15f0f787-bb64-4e0d-a9c1-859606b27a69', 'Let us do (chapter 2): multiple-choice, relation between A and B, order-of-operations calculations, making stories.', 5, 'mathematics', 2, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 29, 36, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('c9dcacd3-d5ae-4d7f-a431-b481a2c354e6', 'Let us do (chapter 2, continued): word problems with brackets, sum/difference, ages and unitary method.', 5, 'mathematics', 2, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 30, 37, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('db630fa9-59ca-4df1-a90e-1e5e5b42baa6', 'Multiples and common multiples. Chapter 3 opener. Multiples: the product of a number and any whole number. Worked example: Multiples of 4: 4, 8, 12, 16, 20…; multiples of 3: 3, 6, 9, 12…', 5, 'mathematics', 3, 'c3-l1', 'g5m-c3-multiples', 'Multiples and common multiples', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 31, 38, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('bbe41711-8b5f-4066-ad67-775c81a6aa8d', 'Multiples and common multiples. Common multiples of two numbers found from lists of multiples. Worked example: Common multiples of 3 and 4 are 12, 24, 36…', 5, 'mathematics', 3, 'c3-l1', 'g5m-c3-multiples', 'Multiples and common multiples', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 32, 39, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('3755c797-bf2a-47ac-a93e-e3eea0456848', 'Least common multiple (LCM). Least common multiple (LCM): the smallest of the common multiples; finding the LCM of two numbers. Worked example: LCM of 3 and 5 is 15 (chocolates shared among 3 or 5 friends)', 5, 'mathematics', 3, 'c3-l2', 'g5m-c3-lcm', 'Least common multiple (LCM)', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 33, 40, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('62ad77bb-7f4e-4312-ab98-ad8c7b95b689', 'Least common multiple (LCM). LCM of three numbers from lists of multiples; tiling a square with 9 cm × 6 cm tiles; bells ringing together. Worked example: LCM of 6, 8 and 12 is 24', 5, 'mathematics', 3, 'c3-l2', 'g5m-c3-lcm', 'Least common multiple (LCM)', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 34, 41, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('2b586948-94eb-4c1c-a25d-beb619dfa52c', 'Prime factors and LCM using prime factors. Prime and composite numbers; expressing a number as a product of prime factors (prime factorisation).', 5, 'mathematics', 3, 'c3-l3', 'g5m-c3-prime-factorisation', 'Prime factors and LCM using prime factors', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 35, 42, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('8afcd980-2431-4c2a-a619-ff3dafad49c4', 'Prime factors and LCM using prime factors. Finding the LCM with prime factors: multiply the common factors and the other factors. Worked example: LCM of 12 and 15 = 3 × 2 × 2 × 5 = 60 (two buses leave together again after 60 minutes)', 5, 'mathematics', 3, 'c3-l3', 'g5m-c3-prime-factorisation', 'Prime factors and LCM using prime factors', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 36, 43, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('02c21a40-8a1f-4ac2-a8ae-9de47e993c3c', 'Divisibility by 3 and 4. Divisibility by 3: a number is divisible by 3 if the sum of its digits is divisible by 3. Worked example: 432 → 4 + 3 + 2 = 9, divisible by 3', 5, 'mathematics', 3, 'c3-l4', 'g5m-c3-divisibility-3-4', 'Divisibility by 3 and 4', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 37, 44, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('dedad483-85e1-45c1-a03b-1427fc3ae382', 'Divisibility by 3 and 4. Divisibility by 4: a number is divisible by 4 if the number formed by its tens and ones digits is 00 or divisible by 4. Worked example: 312 → 12 is divisible by 4', 5, 'mathematics', 3, 'c3-l4', 'g5m-c3-divisibility-3-4', 'Divisibility by 3 and 4', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 38, 45, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('184b02a4-dadf-432e-a89b-3cd0a419e44f', 'LCM by the division method. LCM by the division method: divide by common prime factors, then multiply the divisors and remaining numbers; LCM of numbers with no common prime factor is their product. Worked example: LCM of 12 and 18 = 36; LCM of 12, 14, 18; LCM of 7 and 12 = 84', 5, 'mathematics', 3, 'c3-l5', 'g5m-c3-lcm-division-method', 'LCM by the division method', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 39, 46, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('d9554030-c85d-4eb4-a63e-280fa7201bae', 'Factors. Factors: numbers that divide a number without remainder; 1 and the number itself are always factors. Worked example: Factors of 12 are 1, 2, 3, 4, 6, 12 (sharing 12 sweets)', 5, 'mathematics', 3, 'c3-l6', 'g5m-c3-factors', 'Factors', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 40, 47, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('143b6ea8-e25f-4502-ab0d-2fafad510f4b', 'Highest common factor (HCF). Highest common factor (HCF): the largest of the common factors of two or more numbers. Worked example: Common factors of 8 and 12 are 1, 2, 4 → HCF is 4 (bananas and litchis)', 5, 'mathematics', 3, 'c3-l7', 'g5m-c3-hcf', 'Highest common factor (HCF)', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 41, 48, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('02a6e85e-a259-4b80-ac43-205eeaee1ca2', 'Highest common factor (HCF). HCF of numbers whose only common factor is 1; HCF from a number line; making a story for HCF. Worked example: HCF of 13 and 16 is 1', 5, 'mathematics', 3, 'c3-l7', 'g5m-c3-hcf', 'Highest common factor (HCF)', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 42, 49, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('d01a48ac-79db-4bf8-a874-2e3775067c0b', 'Highest common factor (HCF). HCF of three numbers from lists of factors. Worked example: HCF of 15, 18 and 24 is 3 (oil, flour and rice for families)', 5, 'mathematics', 3, 'c3-l7', 'g5m-c3-hcf', 'Highest common factor (HCF)', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 43, 50, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('225e16b7-8de8-45d8-ad52-514c80eb84a3', 'HCF using prime factors. HCF with prime factors: the product of the common prime factors. Worked example: HCF of 77 and 22 is 11 (ribbons); HCF of 63 and 72', 5, 'mathematics', 3, 'c3-l8', 'g5m-c3-hcf-prime-factors', 'HCF using prime factors', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 44, 51, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('5668a1e5-a3de-471c-ad6d-396565d784b5', 'HCF using prime factors. HCF by dividing with common prime factors; cutting a 12 cm × 18 cm paper into the largest squares. Worked example: HCF of 28, 42 and 56 is 14', 5, 'mathematics', 3, 'c3-l8', 'g5m-c3-hcf-prime-factors', 'HCF using prime factors', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 45, 52, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('436d8060-1d9f-4038-a78a-5673118429ac', 'Let us try (self-check) for multiples, LCM, divisibility by 3 and 4, factors and HCF.', 5, 'mathematics', 3, null, null, 'let_us_try', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 46, 53, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('ba39c9d3-7ce9-4e49-aa78-ee5a823de628', 'Let us do (chapter 3): multiple-choice, divisibility checks, finding LCM and HCF.', 5, 'mathematics', 3, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 47, 54, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('49213139-2ae0-4e3f-a872-d70943401df6', 'Let us do (chapter 3, continued): word problems on LCM and HCF (chocolates, trees and lamp posts, bells, carpets, mangoes and litchis).', 5, 'mathematics', 3, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 48, 55, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('30ced376-185f-4f09-ad0f-026a226eb878', 'Mixed and improper fractions. Chapter 4 opener. Converting a mixed fraction into an improper fraction: multiply the denominator by the whole part and add the numerator.', 5, 'mathematics', 4, 'c4-l1', 'g5m-c4-mixed-improper', 'Mixed and improper fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 49, 56, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('c1d6e98d-f7ec-475d-a879-b1f78a2e105d', 'Mixed and improper fractions. Converting an improper fraction into a mixed fraction by dividing the numerator by the denominator. Worked example: 9/4 = 2 1/4 because 9 ÷ 4 = 2 remainder 1', 5, 'mathematics', 4, 'c4-l1', 'g5m-c4-mixed-improper', 'Mixed and improper fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 50, 57, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('dfa29651-8cdd-4842-a786-e9372e595632', 'Equivalent fractions. Equivalent fractions: multiply or divide numerator and denominator by the same number.', 5, 'mathematics', 4, 'c4-l2', 'g5m-c4-equivalent-fractions', 'Equivalent fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 51, 58, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('4b2256e8-a1ca-4f3f-ad7f-20eb23f81f28', 'Fractions in lowest form. Lowest form of a fraction: divide numerator and denominator by their common factor / HCF. Worked example: 9/36 = 1/4; 15/45 = 1/3', 5, 'mathematics', 4, 'c4-l3', 'g5m-c4-lowest-form', 'Fractions in lowest form', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 52, 59, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('ea4c6695-f82f-4ebe-a770-c82f36696ab8', 'Comparing fractions using a common denominator. Comparing fractions with different denominators by converting to a common denominator. Worked example: 3/4 = 9/12 and 2/3 = 8/12, so 3/4 > 2/3 (ribbons)', 5, 'mathematics', 4, 'c4-l4', 'g5m-c4-compare-fractions', 'Comparing fractions using a common denominator', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 53, 60, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('d1ad5729-d2fe-47a2-ad9d-e9cfb36487b7', 'Comparing fractions using a common denominator. Comparing fractions using the LCM of the denominators as the common denominator. Worked example: Denominators 6 and 9 → LCM 18', 5, 'mathematics', 4, 'c4-l4', 'g5m-c4-compare-fractions', 'Comparing fractions using a common denominator', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 54, 61, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('0aa928e5-cd13-4504-ad34-5c1645fc46bf', 'Comparing fractions using a common denominator. Practice comparing two and three fractions with common denominators using <, > or =.', 5, 'mathematics', 4, 'c4-l4', 'g5m-c4-compare-fractions', 'Comparing fractions using a common denominator', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 55, 62, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('c994a39f-c0a1-4590-aab2-f1773f5b869b', 'Adding fractions with different denominators. Adding fractions with different denominators: convert to a common denominator first, then add. Worked example: Water in two bottles added after making the denominators equal', 5, 'mathematics', 4, 'c4-l5', 'g5m-c4-add-fractions', 'Adding fractions with different denominators', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 56, 63, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('67248df2-c3b6-4fc7-a949-83c540b7e00d', 'Subtracting fractions with different denominators. Subtracting fractions with different denominators: convert to a common denominator first, then subtract. Worked example: Milk remaining after drinking part of it', 5, 'mathematics', 4, 'c4-l6', 'g5m-c4-subtract-fractions', 'Subtracting fractions with different denominators', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 57, 64, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('a2a57ad6-b78c-41f2-a218-ce0af591e2cf', 'Calculating with several fractions. Adding and subtracting, giving answers in lowest form; calculating with three fractions; adding lengths.', 5, 'mathematics', 4, 'c4-l7', 'g5m-c4-fractions-mixed-operations', 'Calculating with several fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 58, 65, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('088d170f-ae83-49fe-a0e3-805e9c11ed7d', 'Adding and subtracting mixed fractions. Adding mixed fractions in two ways: add whole parts and fractions separately, or convert to improper fractions first.', 5, 'mathematics', 4, 'c4-l8', 'g5m-c4-mixed-fraction-operations', 'Adding and subtracting mixed fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 59, 66, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('cb258bbb-8024-4d89-aac0-955415b71d30', 'Adding and subtracting mixed fractions. Calculating with mixed fractions (addition and subtraction together) and making stories for fraction sums.', 5, 'mathematics', 4, 'c4-l8', 'g5m-c4-mixed-fraction-operations', 'Adding and subtracting mixed fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 60, 67, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('7658ab2c-4bdd-4374-a9a6-9933a4aa54dc', 'Let us try (self-check) for proper fractions, lowest form and fraction calculations.', 5, 'mathematics', 4, null, null, 'let_us_try', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 61, 68, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('e251745a-54ac-402e-aaf9-685ad7ff21cc', 'Let us do (chapter 4): multiple-choice, calculations with fractions and word problems (ribbons, juice, distances).', 5, 'mathematics', 4, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 62, 69, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('22c0e7b7-fbe5-4c32-a30a-0231811cbeac', 'Tenths, hundredths and thousandths. Chapter 5 opener. Writing a length in metres as a decimal; tenths and hundredths; common and decimal fractions of coloured parts. Worked example: 1 m 30 cm = 1.3 m', 5, 'mathematics', 5, 'c5-l1', 'g5m-c5-decimal-place-value', 'Tenths, hundredths and thousandths', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 63, 70, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('6d6c20bd-2496-40ab-a060-f0c6d7e60935', 'Tenths, hundredths and thousandths. Tenths (0.1), hundredths (0.01) and thousandths (0.001); place names and reading a decimal; grams as thousandths of a kilogram. Worked example: 1225 g = 1.225 kg; reading 1.235', 5, 'mathematics', 5, 'c5-l1', 'g5m-c5-decimal-place-value', 'Tenths, hundredths and thousandths', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 64, 71, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('a9020fc9-105a-41c5-a515-8f50f55ce012', 'Tenths, hundredths and thousandths. How many 1s, 0.1s, 0.01s and 0.001s make a number; decimals on a number line. Worked example: 1.469 = one 1, four 0.1, six 0.01, nine 0.001', 5, 'mathematics', 5, 'c5-l1', 'g5m-c5-decimal-place-value', 'Tenths, hundredths and thousandths', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 65, 72, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('8d2d874c-eb0f-4bc3-aaa3-e305ada5cd71', 'Tenths, hundredths and thousandths. Placing decimals on a number line; expressing an amount of water with tenths and hundredths of a litre.', 5, 'mathematics', 5, 'c5-l1', 'g5m-c5-decimal-place-value', 'Tenths, hundredths and thousandths', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 66, 73, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('88ecfac0-b9fa-44c3-a0e9-0f1eb729a9e7', 'Tenths, hundredths and thousandths. Expressing an amount to thousandths and reading it with the place-value chart. Worked example: 1.358 litres = one point three five eight', 5, 'mathematics', 5, 'c5-l1', 'g5m-c5-decimal-place-value', 'Tenths, hundredths and thousandths', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 67, 74, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('f1e4ed43-8588-4035-a074-5093d0ce1acf', 'Converting between decimal and common fractions. Conversion to common fractions: write the decimal with denominator 10, 100 or 1000 and reduce to lowest form. Worked example: 0.3 = 3/10, 0.15 = 15/100, 0.008 = 8/1000', 5, 'mathematics', 5, 'c5-l2', 'g5m-c5-decimal-fraction-conversion', 'Converting between decimal and common fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 68, 75, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('e27460cd-ade3-413b-a2f2-ef0a214aac23', 'Converting between decimal and common fractions. Conversion to decimal fractions: make the denominator 10, 100 or 1000 using equivalent fractions. Worked example: 3/5 = 6/10 = 0.6; 7/25 = 28/100 = 0.28; 173/500 = 0.346', 5, 'mathematics', 5, 'c5-l2', 'g5m-c5-decimal-fraction-conversion', 'Converting between decimal and common fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 69, 76, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('ab96a98e-d921-4041-ae73-03745f54ec67', 'Comparing decimal fractions. Comparing decimal fractions using the place-value chart. Worked example: 0.015 < 0.478 < 1.23', 5, 'mathematics', 5, 'c5-l3', 'g5m-c5-compare-decimals', 'Comparing decimal fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 70, 77, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('5abbc40b-4ce6-4d9f-a043-55ff5af77323', 'Comparing decimal fractions. Comparing decimals by reading the digits without the decimal point; ordering from smallest to largest. Worked example: 15 < 478 < 1230 so 0.015 < 0.478 < 1.23', 5, 'mathematics', 5, 'c5-l3', 'g5m-c5-compare-decimals', 'Comparing decimal fractions', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 71, 78, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('6130e6ca-2505-4002-a3ce-b7c12274b5a8', 'Addition and subtraction of decimal numbers. Addition and subtraction of decimal numbers vertically: line up the decimal points. Worked example: 25.52 + 12.65 = 38.17 km; 4.80 − 3.59 = 1.21 kg', 5, 'mathematics', 5, 'c5-l4', 'g5m-c5-decimal-add-subtract', 'Addition and subtraction of decimal numbers', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 72, 79, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('427a5277-7db9-4b97-ad5b-8be419d5022b', 'Addition and subtraction of decimal numbers. Adding and subtracting decimals to hundredths and thousandths; writing extra zeros (4 as 4.00, 0.5 as 0.50). Worked example: 4.06 + 2.94 = 7; 4 − 2.31; 3.75 − 0.5; 7.58 − 6.87 = 0.71', 5, 'mathematics', 5, 'c5-l4', 'g5m-c5-decimal-add-subtract', 'Addition and subtraction of decimal numbers', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 73, 80, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('39244dfc-fc93-4fb6-a151-8bce6e888ad5', 'Multiplication of decimals by whole numbers. Multiplication of decimals by a whole number, thinking in units of 0.1, 0.01 or 0.001. Worked example: 0.2 × 4 = 0.8 (milk packets); 0.004 × 7', 5, 'mathematics', 5, 'c5-l5', 'g5m-c5-decimal-multiply-whole', 'Multiplication of decimals by whole numbers', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 74, 81, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('e73ea3bd-7b42-4536-a5c0-3c4b4ed72b91', 'Multiplication of decimals by whole numbers. Rule for multiplying decimals: multiply as whole numbers, then place the decimal point by counting decimal places. Worked example: 2.13 × 6 = 12.78', 5, 'mathematics', 5, 'c5-l5', 'g5m-c5-decimal-multiply-whole', 'Multiplication of decimals by whole numbers', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 75, 82, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('ad04d1ff-2a7a-4dc0-aa10-27be84a170e8', 'Multiplying by 10, 100, 1000 and decimal by decimal. Multiplying decimals by 10, 100 and 1000: the decimal point moves right as many places as there are zeros. Worked example: 2.395 × 10 = 23.95; 2.395 × 100 = 239.5', 5, 'mathematics', 5, 'c5-l6', 'g5m-c5-decimal-multiply-decimal', 'Multiplying by 10, 100, 1000 and decimal by decimal', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 76, 83, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('65688971-4c25-4a63-a052-c0540c1d42cc', 'Multiplying by 10, 100, 1000 and decimal by decimal. Multiplying a decimal by a decimal: the product has as many decimal places as both numbers together. Worked example: 0.2 × 0.16 = 0.032; 2.8 × 1.75 = 4.9', 5, 'mathematics', 5, 'c5-l6', 'g5m-c5-decimal-multiply-decimal', 'Multiplying by 10, 100, 1000 and decimal by decimal', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 77, 84, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('374b5580-640c-433d-ae94-33d74562d712', 'Division of decimal numbers by whole numbers. Division of decimal numbers by a whole number, thinking in units of 0.1, 0.01, 0.001. Worked example: 0.6 ÷ 3 = 0.2 (milk shared among 3 students)', 5, 'mathematics', 5, 'c5-l7', 'g5m-c5-decimal-divide-whole', 'Division of decimal numbers by whole numbers', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 78, 85, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('e0b7bb22-61c6-4e5b-a39f-2f81e7c332c3', 'Division of decimal numbers by whole numbers. Dividing a whole number by a larger whole number to get a decimal quotient. Worked example: 2 ÷ 5 = 0.4 (juice shared among 5 students); 7.2 ÷ 3', 5, 'mathematics', 5, 'c5-l7', 'g5m-c5-decimal-divide-whole', 'Division of decimal numbers by whole numbers', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 79, 86, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('da4a3429-60d5-456d-ae0f-1215855cf6b4', 'Division of decimal numbers by whole numbers. Long division of decimals: put the decimal point in the quotient above the one in the dividend; add zeros to continue dividing. Worked example: 4.92 ÷ 6 = 0.82; 5 ÷ 8 = 0.625', 5, 'mathematics', 5, 'c5-l7', 'g5m-c5-decimal-divide-whole', 'Division of decimal numbers by whole numbers', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 80, 87, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('8fd8eac7-8e9e-49ef-a72f-08d1ff41ec20', 'Division of decimal numbers by whole numbers. Dividing a decimal by a two-digit whole number; division word problems. Worked example: 98.7 ÷ 21 = 4.7', 5, 'mathematics', 5, 'c5-l7', 'g5m-c5-decimal-divide-whole', 'Division of decimal numbers by whole numbers', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 81, 88, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('420b5044-974d-4140-a6f7-a297c2795baf', 'Dividing decimals by 10 and 100. Dividing decimals by 10 and 100: the decimal point moves left as many places as there are zeros. Worked example: 24.3 ÷ 10 = 2.43; 24.3 ÷ 100 = 0.243', 5, 'mathematics', 5, 'c5-l8', 'g5m-c5-decimal-divide-10-100', 'Dividing decimals by 10 and 100', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 82, 89, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('f7083a8b-06d6-4761-ad29-1c222a0485d7', 'Dividing by a decimal number. Dividing a whole number by a decimal: two ways of thinking (units of 0.1, or multiplying both numbers by 10). Worked example: 12 ÷ 2.4 = 5 (weight per metre of an iron bar)', 5, 'mathematics', 5, 'c5-l9', 'g5m-c5-divide-by-decimal', 'Dividing by a decimal number', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 83, 90, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('ad5c249c-fa1c-4117-a032-d3b8d9856ce1', 'Dividing by a decimal number. Dividing by decimals practice; property of division: multiplying or dividing dividend and divisor by the same number keeps the quotient the same. Worked example: 24 ÷ 40 = 2.4 ÷ 4 = 1.2 ÷ 2 = 0.6', 5, 'mathematics', 5, 'c5-l9', 'g5m-c5-divide-by-decimal', 'Dividing by a decimal number', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 84, 91, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('de5da717-1117-47f8-a3a1-43a58140bc13', 'Dividing by a decimal number. Dividing a decimal by a decimal: multiply both by 10 or 100 to make the divisor a whole number. Worked example: 2.4 ÷ 1.6 = 24 ÷ 16 = 1.5; 4.65 ÷ 1.5 = 3.1; 2.16 ÷ 0.24 = 9', 5, 'mathematics', 5, 'c5-l9', 'g5m-c5-divide-by-decimal', 'Dividing by a decimal number', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 85, 92, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('f7482ca0-de85-4f06-a277-95e42a1009d6', 'Dividing by a decimal number. Practice dividing by decimals, finding mistakes in calculations, and an area word problem.', 5, 'mathematics', 5, 'c5-l9', 'g5m-c5-divide-by-decimal', 'Dividing by a decimal number', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 86, 93, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('78c4034c-86be-47a3-a279-36fd325083aa', 'Let us try (self-check) for decimal place value, making numbers from cards and unit fractions of measures.', 5, 'mathematics', 5, null, null, 'let_us_try', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 87, 94, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('d7f3d9c0-bc94-446f-af6a-27577ed0f3b8', 'Let us try (continued): multiplying and dividing by 10 and 100, fill in the blanks, speed word problem.', 5, 'mathematics', 5, null, null, 'let_us_try', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 88, 95, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('58533beb-40cc-4de2-a83b-50432f8a900b', 'Let us do (chapter 5): multiple-choice, number line, place value, conversions between fractions and decimals.', 5, 'mathematics', 5, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 89, 96, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('59e75151-0d4d-4f71-a337-5330ec49fca6', 'Let us do (chapter 5, continued): multiplying and dividing decimals and word problems.', 5, 'mathematics', 5, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 90, 97, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('7a9e2f0a-0b3c-4af1-a179-be8a4d52fd31', 'What percent means. Chapter 6 opener. Percentage: comparing parts of different totals by making the denominator 100; the % symbol. Worked example: 20/50 = 40/100 = 40% and 12/25 = 48/100 = 48%', 5, 'mathematics', 6, 'c6-l1', 'g5m-c6-percent-meaning', 'What percent means', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 91, 98, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('8a439c33-cd6b-41e0-afbb-7d320d2b32a3', 'What percent means. Writing percentages as fractions with denominator 100 and as decimals; colouring a percentage of a grid. Worked example: 15% = 15/100 = 0.15', 5, 'mathematics', 6, 'c6-l1', 'g5m-c6-percent-meaning', 'What percent means', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 92, 99, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('8e2ea8da-426d-4179-a921-cebd8c9e0478', 'Finding a percentage of a quantity. Expressing fractions as percentages; finding a percentage of a quantity using a fraction of 100 or the unitary method. Worked example: 42% of 50 students = 21 girls', 5, 'mathematics', 6, 'c6-l2', 'g5m-c6-percent-of-quantity', 'Finding a percentage of a quantity', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 93, 100, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('57cb67bc-5f58-4382-af73-68f07bd5b17e', 'Finding a percentage of a quantity. Finding a part from a percentage and finding what percent one quantity is of another. Worked example: 80% of 1280 = 1024 farmers; 12 of 30 plants = 40%', 5, 'mathematics', 6, 'c6-l2', 'g5m-c6-percent-of-quantity', 'Finding a percentage of a quantity', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 94, 101, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('0bdd259a-8704-4b13-a563-01a48b093b24', 'Comparing and changing by a percentage. Reading percentages from bars; percentage increase. Worked example: Population 2800 increases by 3%', 5, 'mathematics', 6, 'c6-l3', 'g5m-c6-percent-compare-change', 'Comparing and changing by a percentage', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 95, 102, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('23070058-e495-4447-a8bd-d1209defaecf', 'Comparing and changing by a percentage. Comparing two groups using percentages (literacy in two cities). Worked example: 34260 of 45680 = 75% and 36764 of 52520 = 70%', 5, 'mathematics', 6, 'c6-l3', 'g5m-c6-percent-compare-change', 'Comparing and changing by a percentage', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 96, 103, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('482cf75d-6edf-457b-aadb-dfc386f7e62d', 'Profit and loss. Profit and loss: profit = selling price − cost price, loss = cost price − selling price; profit or loss percent is calculated on the cost price. Worked example: Bought at 50, sold at 58 → 16% profit; bought at 15, sold at 12 → 20% loss', 5, 'mathematics', 6, 'c6-l4', 'g5m-c6-profit-loss', 'Profit and loss', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 97, 104, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('62c9b968-ddd1-44f5-ab16-e9c0e3d4373c', 'Profit and loss. Finding the cost price from the selling price and the profit or loss percent. Worked example: Sold at 85400 taka with 22% profit → cost price 70000 taka', 5, 'mathematics', 6, 'c6-l4', 'g5m-c6-profit-loss', 'Profit and loss', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 98, 105, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('f9687a78-7b98-46c0-a66e-70db16b29e09', 'Profit on principal (rate of profit). Profit on money invested in a bank: principal, annual profit rate; Profit = Principal × Profit rate. Worked example: 20000 taka at 7% gives 1400 taka a year', 5, 'mathematics', 6, 'c6-l5', 'g5m-c6-profit-on-principal', 'Profit on principal (rate of profit)', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 99, 106, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('6f989e3a-9ac4-405f-acff-cdf49b814d30', 'Profit on principal (rate of profit). Finding the rate of profit; profit for several years is the annual profit times the number of years. Worked example: 20000 taka at 6% for 3 years', 5, 'mathematics', 6, 'c6-l5', 'g5m-c6-profit-on-principal', 'Profit on principal (rate of profit)', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 100, 107, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('fa99f62d-9ee8-468a-a729-fdf62ac66c87', 'Profit on principal (rate of profit). Finding the annual profit rate from total profit over several years; profit for part of a year (months). Worked example: 5000 taka earns 2700 in 6 years → 9%; 10000 taka at 6% for 9 months', 5, 'mathematics', 6, 'c6-l5', 'g5m-c6-profit-on-principal', 'Profit on principal (rate of profit)', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 101, 108, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('e3639bd2-e4b1-495f-ab56-f571094d009a', 'Let us try (self-check) for percentages, cost price, and profit on principal.', 5, 'mathematics', 6, null, null, 'let_us_try', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 102, 109, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('a7e1c468-406c-45ab-a1e7-1d4f2da33f32', 'Let us do (chapter 6): multiple-choice, percentages of quantities and fill in the blanks.', 5, 'mathematics', 6, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 103, 110, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('933c1d6c-0de2-49b0-a03c-990f2204a285', 'Let us do (chapter 6, continued): word problems on percentage, profit, discount and bank profit.', 5, 'mathematics', 6, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 104, 111, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('5057ec84-49ad-4438-a167-77f3b8fc3685', 'What an average is. Chapter 7 opener. Average: the sum of values of the same kind divided by the number of values. Worked example: Marbles 18, 22, 28, 16 → 84 ÷ 4 = 21 each', 5, 'mathematics', 7, 'c7-l1', 'g5m-c7-average-meaning', 'What an average is', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 105, 112, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('45a70198-9371-4fc5-a910-a04b08f6b35d', 'What an average is. Finding averages; finding a missing value from the average: total = average × number of values. Worked example: Average of 3 baskets is 25, two baskets have 18 and 21 → third has 36', 5, 'mathematics', 7, 'c7-l1', 'g5m-c7-average-meaning', 'What an average is', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 106, 113, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('4ae0bde3-1e7b-4b35-a0ab-73de481c8458', 'Finding totals and missing values from an average. Average from a table of daily values; combining averages of two groups. Worked example: Metres walked on 7 days ÷ 7', 5, 'mathematics', 7, 'c7-l2', 'g5m-c7-average-missing-value', 'Finding totals and missing values from an average', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 107, 114, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('51513a98-a179-4c62-a98d-0862ffd85982', 'Average problems from everyday data. Average as ''levelling'' amounts; average temperature from a 12-month table. Worked example: Glasses with 100, 80 and 150 mL → 110 mL each', 5, 'mathematics', 7, 'c7-l3', 'g5m-c7-average-word-problems', 'Average problems from everyday data', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 108, 115, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('27d3bb72-8137-4694-a69a-aa4f7479e6ce', 'Average problems from everyday data. Finding one value when the average changes after adding a value; averages of overlapping groups. Worked example: 30 students average 10 years, with the teacher average 11 → teacher is 41', 5, 'mathematics', 7, 'c7-l3', 'g5m-c7-average-word-problems', 'Average problems from everyday data', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 109, 116, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('4a7b82eb-a9ef-4bd3-abb2-9d307d6f579f', 'Average problems from everyday data. Practice problems on averages from groups and tables.', 5, 'mathematics', 7, 'c7-l3', 'g5m-c7-average-word-problems', 'Average problems from everyday data', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 110, 117, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('e95505d8-d492-4c81-a7b5-17a059720d2e', 'An easy way to find an average. An easy way to find an average: take differences from a base value (or the lowest value), average the differences and add back. Worked example: Heights 145, 149, 133, 152, 142 → 130 + 14.2 = 144.2 cm', 5, 'mathematics', 7, 'c7-l4', 'g5m-c7-average-easy-method', 'An easy way to find an average', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 111, 118, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('98b305a6-51b7-4d06-a981-05438ed0af35', 'An easy way to find an average. Using the easy method for group heights; why the average of two averages is wrong when group sizes differ. Worked example: Runs against India (5 matches) and Sri Lanka (3 matches)', 5, 'mathematics', 7, 'c7-l4', 'g5m-c7-average-easy-method', 'An easy way to find an average', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 112, 119, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('99988df0-34e6-4ef4-acf1-7fb197b6e3db', 'Let us try (self-check) for averages.', 5, 'mathematics', 7, null, null, 'let_us_try', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 113, 120, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('d5f3b78a-9758-4b47-a955-cc80b7378ed8', 'Let us do (chapter 7): multiple-choice and word problems on averages.', 5, 'mathematics', 7, null, null, 'let_us_do', 'exercise', 'Experimental Edition, academic year 2026 (first print September 2025)', 114, 121, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('4b414035-5865-4cb0-aa6e-58d0ff19c9bd', 'Length measurement. Chapter 8 opener. Length measurement: kilometre, hectometre, decametre, metre, decimetre, centimetre, millimetre; each unit is 10 times the next smaller one. Worked example: 1 km = 1000 m; 1 cm = 0.01 m', 5, 'mathematics', 8, 'c8-l1', 'g5m-c8-length-units', 'Length measurement', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 115, 122, 'en', true) on conflict (id) do update set content = excluded.content;
insert into public.curriculum_chunks (id, content, grade, subject, chapter, lesson_id, concept_id, topic, kind, source_edition, page_ref, pdf_page, language, approved) values ('d5d22c31-e54e-447b-aa52-6742f7aefbcb', 'Length measurement. Calculating with lengths and expressing in given units; ordering lengths; word problems. Worked example: 1 m 25 cm × 3 = 375 cm', 5, 'mathematics', 8, 'c8-l1', 'g5m-c8-length-units', 'Length measurement', 'explanation', 'Experimental Edition, academic year 2026 (first print September 2025)', 116, 123, 'en', true) on conflict (id) do update set content = excluded.content;
